(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*18 + Math.cos(y*0.02-t*0.25)*12;
  const w1y = Math.cos(y*0.015-t*0.28)*18 + Math.sin(x*0.018+t*0.32)*12;
  const w2x = Math.sin(x*0.035+t*0.5)*6 + Math.cos(y*0.04-t*0.45)*4;
  const w2y = Math.cos(y*0.03-t*0.48)*6 + Math.sin(x*0.038+t*0.52)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, -0.5],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, -0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, -0.4],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.65+1)*40, 0.11, 2.1, 0.9],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.75+4)*50, 0.065, 2.4, -0.6]
  ];
  let aS = 0, iS = 0, mS = 0;
  for (const [sX, sY, f, sp, ph] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const w = 1/(1+d*0.003);
    aS += Math.sin(d*f - t*sp + ph) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5 + ph*0.5) * w;
    mS += Math.sin(d*f*1.3 - t*sp*0.8 + ph*2) * w;
  }
  const act = aS/8, inh = iS/8, mod = mS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.08+t*0.6)*Math.cos(sy*0.06-t*0.4)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cx, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2)
    + Math.sin(dist*0.065-ang*2-t*0.8)*0.5)*0.35;
  const r1 = act - inh*0.7 + bg*0.3 + spiral;
  const r2 = mod*0.5 + Math.sin(act*inh*2)*0.4 + Math.cos(dist*0.03+t)*0.3;
  const reaction = Math.tanh((r1 + r2*0.4)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5 + Math.sin((sx*2-sy)*0.08+t*0.7)*0.3)*1.5)*0.3;
  const detail = Math.sin(sx*0.4+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
  const blend = reaction*0.65 + cell*0.2 + detail + spiral*0.15;
  const v = blend*0.5+0.5;
  const pal = [[5,12,55],[12,55,95],[18,110,120],[30,160,130],[160,190,60],[220,170,45],[210,110,55],[180,55,60],[120,30,65],[60,18,55],[5,12,55]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.75?1.2:(Math.abs(reaction)>0.5?1.05:0.95);
  const glow = Math.max(0, reaction)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*20)|0
  ];
}
